<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import { loadProgram } from '../data.js'
import { useSeo } from '../../lib/seo.js'
import { Phone, MapPin, Clock, ArrowLeft, Store } from 'lucide-vue-next'
const route = useRoute(), data = ref(null), loading = ref(true), error = ref(''), photo = ref(0)
const program = computed(() => data.value?.program)
const photos = computed(() => data.value?.photos?.length ? data.value.photos : data.value?.image ? [data.value.image] : [])
const phone = computed(() => program.value?.contact_phone || data.value?.location?.phone || '')
const phoneHref = computed(() => 'tel:' + phone.value.replace(/[^+0-9]/g, ''))
const interval = computed(() => ({ monthly:'month', weekly:'week', yearly:'year', session:'session', term:'term' }[program.value?.billing_interval] || 'month'))
async function load() { loading.value = true; error.value = ''; photo.value = 0; try { data.value = await loadProgram(route.params.id) } catch(e) { error.value = 'This listing could not be loaded. Please try again.' } finally { loading.value = false } }
onMounted(load); watch(() => route.params.id, load)
useSeo(() => ({ title: program.value?.name || 'Membership listing', description: program.value?.description?.slice(0,160) || 'Discover an academy and contact the provider directly.', path: `/programs/${route.params.id}` }))
</script>
<template>
  <main class="academy-page">
    <router-link to="/programs" class="academy-back"><ArrowLeft :size="16"/> Explore memberships</router-link>
    <p v-if="loading" class="academy-empty">Loading listing…</p>
    <section v-else-if="error || !program" class="academy-empty"><h1>{{ error ? 'Could not load listing' : 'This listing is not available' }}</h1><p>{{ error || 'Explore other academies and membership listings in your area.' }}</p><button v-if="error" @click="load">Try again</button></section>
    <template v-else>
      <div class="academy-gallery"><img v-if="photos.length" :src="photos[photo]" :alt="program.name"/><div v-else class="academy-fallback"><Store :size="60"/></div><div v-if="photos.length>1" class="academy-thumbs"><button v-for="(src,i) in photos" :key="i" :aria-label="`View photo ${i+1}`" :aria-pressed="photo===i" @click="photo=i"><img :src="src" alt=""/></button></div></div>
      <div class="academy-layout"><article><p class="academy-kicker">{{ program.sport_category || 'MEMBERSHIP & ACADEMY' }}</p><h1>{{ program.name }}</h1><p v-if="data.location" class="academy-location"><MapPin :size="17"/> {{ data.location.name }}</p><section><h2>About this programme</h2><p class="academy-description">{{ program.description || 'Contact the academy to learn about this programme, availability and enrolment.' }}</p></section><section v-if="program.schedule_description"><h2><Clock :size="18"/> Schedule</h2><p class="academy-description">{{ program.schedule_description }}</p></section><section v-if="data.location?.address"><h2>Location</h2><p>{{ data.location.address }}</p></section></article>
      <aside><span class="academy-kicker">CONTACT THE PROVIDER</span><h2>Interested in joining?</h2><p>Ask the academy about availability, enrolment and payment.</p><div class="academy-price"><template v-if="Number(program.monthly_price)>0"><strong>{{ program.currency }} {{ Number(program.monthly_price).toLocaleString() }}</strong><span> / {{ interval }}</span><small>Advertised academy price. Confirm details with the provider.</small></template><strong v-else>Contact for pricing</strong></div><a v-if="phone" :href="phoneHref" class="academy-call"><Phone :size="18"/> Call the academy</a><p class="academy-number">{{ phone }}</p><div class="academy-direct">Enrolment, academy payments and attendance are arranged directly with the provider.</div></aside></div>
    </template>
  </main>
</template>
<style scoped>
