);color:white;font-weight:700;text-decoration:none;margin-top:20px}.academy-number{text-align:center;font-variant-numeric:tabular-nums}.academy-direct{border-top:1px solid var(--border);padding-top:16px;margin-top:16px;color:var(--text-muted);font-size:12px;line-height:1.6}.academy-empty{padding:80px 20px;text-align:center}@media(max-width:700px){.academy-page{padding:20px 16px 60px}.academy-gallery>img,.academy-fallback{height:230px}.academy-layout{grid-template-columns:1fr;gap:20px}.academy-layout h1{font-size:28px}.academy-layout aside{position:static;grid-row:2}}
